class Solution {
    public String toGoatLatin(String sentence){
        Set<Character> vowels=new HashSet<>(Arrays.asList('a','e','i','o','u','A','E','I','O','U'));
        String[] words=sentence.split(" ");
        StringBuilder answer=new StringBuilder();
        for(int i=0;i<words.length;i++){
            if(i>0)answer.append(' ');
            String word=words[i];
            if(!vowels.contains(word.charAt(0)))word=word.substring(1)+word.charAt(0);
            answer.append(word).append("ma");
            for(int count=0;count<=i;count++)answer.append('a');
        }
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun toGoatLatin(sentence:String):String{
        val vowels="aeiouAEIOU".toSet();
        return sentence.split(' ').mapIndexed{
            index,input->var word=input;
            if(word[0] !in vowels)word=word.substring(1)+word[0];
            word+"ma"+"a".repeat(index+1)
        }.joinToString(" ")
    }
}

